(()=>{'use strict';const $=x=>document.getElementById(x);let images=[],gpus=[],quote=null,version=0,autoAttempted=false;async function call(route,body){const r=await fetch('/api/lightcc'+route,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(45000)});const j=await r.json();if(!r.ok)throw Error(j.error||'请求失败');return j}function note(t){$('pickerStatus').textContent=t}function invalidate(){version++;quote=null;$('createRental').disabled=true;$('quoteSummary').hidden=true}async function work(id,fn){$(id).disabled=true;try{await fn()}catch(e){note(e.message)}finally{$(id).disabled=false}}
function isH3(x){return /h3|pika|minimax/i.test(x.title||'')}function rank(x){return x.pinned?-1:isH3(x)?0:/comfy/i.test(x.title||'')?1:2}
function renderImages(){const select=$('rentalImage'),selected=select.value,query=$('imageSearch').value.trim().toLocaleLowerCase(),category=$('imageCategory').value,order=$('imageSort').value;let shown=images.filter(x=>((x.title||'')+' '+x.id).toLocaleLowerCase().includes(query)&&(category==='all'||category==='h3'&&isH3(x)||category==='comfy'&&/comfy/i.test(x.title||'')));shown.sort((a,b)=>(Number(!!b.pinned)-Number(!!a.pinned))||(order==='id'?String(b.id).localeCompare(String(a.id),'en',{numeric:true}):((order==='recommended'?rank(a)-rank(b):0)||(a.title||'').localeCompare(b.title||'','zh-CN',{numeric:true}))));select.replaceChildren(new Option(shown.length?'请选择镜像':'没有匹配镜像',''));const current=images.find(x=>x.id===selected);if(current&&!shown.some(x=>x.id===selected))select.add(new Option('已选：'+current.title+' · #'+current.id,current.id));for(const x of shown)select.add(new Option((x.pinned?'★ 我的镜像 · ':'')+x.title+' · #'+x.id,x.id));select.value=current?selected:'';select.disabled=false;$('imageCount').textContent='显示 '+shown.length+' / '+images.length+' 个镜像'+(current&&!shown.some(x=>x.id===selected)?' · 当前选择保留，不受过滤影响':'')}
for(const id of ['imageSearch','imageCategory','imageSort'])$(id).addEventListener(id==='imageSearch'?'input':'change',()=>{if(images.length)renderImages()});
$('lookupImage').onclick=()=>work('lookupImage',async()=>{const id=$('imageIdLookup').value.trim();if(!/^\d+$/.test(id))throw Error('请输入镜像编号');note('正在向LightCC核对镜像编号…');const j=await call('/image-by-id',{imageId:id});invalidate();images=images.filter(x=>x.id!==j.image.id);images.unshift(j.image);$('imageSearch').value='';$('imageCategory').value='all';$('imageSort').value='recommended';renderImages();$('rentalImage').value=j.image.id;$('rentalImage').dispatchEvent(new Event('change'));note('已加入：'+j.image.title+'，正在读取可用GPU')});
$('loadImages').onclick=()=>work('loadImages',async()=>{note('正在读取LightCC镜像列表…');invalidate();const j=await call('/images');images=j.images;renderImages();const preferred=images.find(x=>String(x.id)==='82761')||images.find(x=>x.pinned);if(preferred){$('rentalImage').value=preferred.id;$('rentalImage').dispatchEvent(new Event('change'));return}$('rentalGpu').disabled=true;note(images.length?'镜像已加载，可以搜索或按分类筛选':'没有可用镜像，请先在LightCC保存或添加镜像')});
document.addEventListener('lightcc-account-status',e=>{if(!e.detail.configured){autoAttempted=false;return}if(!autoAttempted&&$('rentalImage').disabled){autoAttempted=true;$('loadImages').click()}});
function renderGpuCards(loading=false){const box=$('gpuCards');box.replaceChildren();if(loading||!gpus.length){const p=document.createElement('p');p.className='hint gpu-empty';p.textContent=loading?'正在刷新设备库存…':'先选择镜像，或点击刷新GPU读取设备';box.append(p);$('gpuSelection').textContent=loading?'正在读取官方库存…':'尚未选择GPU';return}const selected=$('rentalGpu').value;const rows=gpus.map((x,i)=>({x,i})).sort((a,b)=>Number(selected===String(b.i))-Number(selected===String(a.i))||Number(b.x.available)-Number(a.x.available));for(const {x,i} of rows){const card=document.createElement('button');card.type='button';card.className='gpu-card';card.setAttribute('role','radio');card.setAttribute('aria-checked',String(selected===String(i)));card.setAttribute('aria-label',x.gpu+'，'+x.memory+'GB，'+(x.available?'可用':'暂无库存'));card.disabled=!x.available&&selected!==String(i);const top=document.createElement('span');top.className='gpu-card-top';top.innerHTML='<svg viewBox="0 0 40 40" fill="none" aria-hidden="true"><rect x="7" y="8" width="26" height="24" rx="4" stroke="currentColor" stroke-width="2"/><circle cx="20" cy="20" r="7" stroke="currentColor" stroke-width="2"/><path d="M20 13v14M13 20h14M2 14h5M2 26h5M33 14h5M33 26h5" stroke="currentColor" stroke-width="2"/></svg>';const name=document.createElement('strong');name.textContent=x.gpu;top.append(name);const bottom=document.createElement('span');bottom.className='gpu-card-bottom';const memory=document.createElement('span');memory.className='gpu-memory';memory.textContent=x.memory+'GB';const stock=document.createElement('span');stock.className='gpu-stock';stock.textContent=selected===String(i)?(x.available?'✓ 已选择':'✓ 已选择 · 新租暂无库存'):x.available?'可新租':'新租暂无库存';bottom.append(memory,stock);card.append(top,bottom);card.onclick=()=>{if(selected===String(i))return;$('rentalGpu').value=String(i);$('rentalGpu').dispatchEvent(new Event('change'))};card.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const available=[...box.querySelectorAll('button:not(:disabled)')],index=available.indexOf(card);const next=e.key==='Home'?0:e.key==='End'?available.length-1:Math.max(0,Math.min(available.length-1,index+(e.key==='ArrowRight'?1:-1)));available[next]?.focus();available[next]?.scrollIntoView({block:'nearest',inline:'nearest'})};box.append(card)}const x=selected!==''?gpus[Number(selected)]:null;$('gpuSelection').textContent=x?('已选：'+x.gpu+' · '+x.memory+'GB'):'点击一张卡片选择GPU'}
$('gpuPrevious').onclick=()=>$('gpuCards').scrollBy({left:-450,behavior:'smooth'});$('gpuNext').onclick=()=>$('gpuCards').scrollBy({left:450,behavior:'smooth'});
async function refreshGpus(){const selected=gpus[Number($('rentalGpu').value)],previous=$('rentalGpu').value!==''&&selected?selected.gpu+'|'+selected.memory:null;invalidate();const own=version,imageId=$('rentalImage').value,s=$('rentalGpu'),button=$('refreshGpu');s.replaceChildren(new Option(imageId?'读取设备中…':'先选择镜像',''));s.disabled=true;button.disabled=true;renderGpuCards(!!imageId);if(!imageId)return;note('正在读取当前镜像的最新设备库存…');try{const j=await call('/gpus?imageId='+encodeURIComponent(imageId));if(own!==version)return;gpus=j.gpus;s.replaceChildren(new Option('请选择GPU与显存',''));gpus.forEach((x,i)=>{const o=new Option(x.gpu+' · '+x.memory+'GB'+(x.available?' · 可用':' · 暂无库存'),String(i));o.disabled=!x.available;s.add(o)});s.disabled=false;let preferred=previous;let saved=null;if(!preferred){try{saved=(await call('/selection')).selection;if(own!==version)return;if(saved&&String(saved.imageId)===imageId)preferred=saved.gpu+'|'+saved.memory}catch{}}const keep=gpus.findIndex(x=>x.gpu+'|'+x.memory===preferred);if(keep>=0&&saved)$('rentalCount').value=saved.count;if(keep>=0){s.options[keep+1].disabled=false;s.value=String(keep);if(gpus[keep].available)s.dispatchEvent(new Event('change'))}renderGpuCards();note('库存已刷新 · '+new Date().toLocaleTimeString()+' · 可用 '+gpus.filter(x=>x.available).length+' 种设备；选中GPU后自动显示费率。')}catch(e){if(own===version){gpus=[];renderGpuCards();note(e.message)}}finally{if(imageId===$('rentalImage').value)button.disabled=false}}
$('rentalImage').onchange=()=>{gpus=[];refreshGpus()};$('refreshGpu').onclick=refreshGpus;
$('rentalGpu').onchange=()=>{invalidate();const x=gpus[Number($('rentalGpu').value)];if(x){$('rentalCount').max=Math.min(8,x.max);if(Number($('rentalCount').value)>x.max)$('rentalCount').value=1}renderGpuCards();if($('rentalGpu').value!=='')requestQuote()};let quoteTimer; $('rentalCount').oninput=()=>{invalidate();clearTimeout(quoteTimer);quoteTimer=setTimeout(requestQuote,400)};
async function requestQuote(){invalidate();const own=version,x=gpus[Number($('rentalGpu').value)];if(!x||$('rentalGpu').value==='')return;const count=Number($('rentalCount').value);if(!Number.isInteger(count)||count<1||count>Math.min(8,x.max))return;note('正在查询所选GPU的实时费率…');try{const j=await call('/quote',{imageId:$('rentalImage').value,gpu:x.gpu,memory:x.memory,count:Number($('rentalCount').value)});if(own!==version)return;quote=j.quote;$('quoteSummary').hidden=false;$('quoteSummary').textContent=quote.title+'\n'+quote.gpu+' · '+quote.memory+'GB × '+quote.count+'\n官方GPU报价：¥'+quote.price+'/小时\n镜像价格字段：'+(quote.imagePrice===null?'未提供，请核实':quote.imagePrice)+'（计费单位以官方说明为准）';await call('/selection',{quoteId:quote.id});if(own!==version)return;localStorage.setItem('frame-video-device','lightcc');$('createRental').disabled=false;note('已保存所选配置 · 点击工作台的生成视频时才启动云端')}catch(e){if(own===version)note('费率查询失败：'+e.message+'；请重新选择GPU或刷新库存重试')}};
$('createRental').onclick=()=>{localStorage.setItem('frame-video-device','lightcc');location.href='/'};
})();
